/* ---------- v71: comparison films — fermentations vs macerations, CO2 vs SO2 ---------- */
/* generic table: column widths, header, rows (strings, current language) */
const zTbl=(x,y,cws,head,rows,o)=>{ o=o||{}; const sz=o.sz||6, lh=sz*1.2, W=cws.reduce((a,b)=>a+b,0); let cy=y, out="";
  const row=(cells,i,hd)=>{ const ls=cells.map((c,j)=>wrapT(String(c),Math.max(4,Math.floor(cws[j]/(sz*.53))))); const h=Math.max(...ls.map(l=>l.length))*lh+5; let cx=x;
    let g=`<rect x="${x}" y="${cy}" width="${W}" height="${h}" rx="${hd?3:0}" fill="${hd?"#4a0f22":(o.hl===i?"rgba(212,162,58,.4)":(i%2?"rgba(255,248,232,.07)":"rgba(255,248,232,.15)"))}"/>`;
    ls.forEach((l,j)=>{ l.forEach((t,k)=>{ g+=`<text x="${cx+3}" y="${cy+lh+1.4+k*lh}" font-size="${sz}" fill="${hd||j===0?"#f3cd8a":"#fff4dc"}" font-family="DM Sans,system-ui,sans-serif" font-weight="${hd||j===0?800:600}">${esc(t)}</text>`; }); cx+=cws[j]; });
    cy+=h; return g; };
  out+=row(head,0,1); rows.forEach((r,i)=>{ out+=fD((o.d0==null?.3:o.d0)+i*(o.dd||.35),row(r,i)); });
  return `<g>${out}</g>`; };
/* winemaking timeline with process bars */
const ZST=[I3("Uva","Raisin","Grapes"),I3("Pigiatura","Foulage","Crushing"),I3("Fermentazione alcolica","Fermentation alcoolique","Alcoholic fermentation"),I3("Svinatura","Écoulage","Draining off"),I3("Malolattica","Malolactique","Malolactic"),I3("Affinamento","Élevage","Maturation"),I3("Bottiglia","Bouteille","Bottle")];
const zTL=(bars,o)=>{ o=o||{}; const X=i=>24+i*45.3, Y=142; let g=`<path d="M${X(0)} ${Y}H${X(6)}" stroke="rgba(255,244,220,.45)" stroke-width="2"/>`;
  ZST.forEach((s,i)=>{ const on=o.hi&&o.hi.includes(i); g+=`<circle cx="${X(i)}" cy="${Y}" r="${on?6:4.5}" fill="${on?"#d4a23a":"#fbf3e2"}" stroke="#4a0f22"/>`+fT(X(i),Y+16,tx(s),6.2,on?"#f3cd8a":"#fff4dc","middle",700,11); });
  bars.forEach(([a,b,lab,col,row],k)=>{ const yy=Y-18-(row||0)*19, hw=Math.max(14,lab.length*1.75+5), x0=a===b?X(a)-hw:X(a)-6, x1=a===b?X(a)+hw:X(b)+6;
    g+=fD(.3+k*.45,`<rect x="${x0}" y="${yy-7}" width="${x1-x0}" height="14" rx="7" fill="${col}"/>${fT((x0+x1)/2,yy+2.4,lab,6,"#fff","middle",800)}`); });
  return g; };
/* organisms */
const zYeastBig=(x,y,s,lab)=>`<g transform="translate(${x} ${y}) scale(${s||1})"><ellipse rx="16" ry="12" fill="#efe1b8" stroke="#b39a5c" stroke-width="1.2"/><ellipse cx="-4" cy="-2" rx="5" ry="4" fill="#d9c58c"/><ellipse cx="15" cy="-10" rx="6" ry="5" fill="#efe1b8" stroke="#b39a5c"><animate attributeName="rx" values="2;6;2" dur="2.4s" repeatCount="indefinite"/><animate attributeName="ry" values="1.6;5;1.6" dur="2.4s" repeatCount="indefinite"/></ellipse></g>${lab?fT(x,y+(s||1)*22,lab,6.4,"#f3cd8a","middle",800,22):""}`;
const zBactBig=(x,y,col,lab)=>`<g transform="translate(${x} ${y})"><g><animateTransform attributeName="transform" type="translate" values="0 0;5 -3;0 0" dur="2.6s" repeatCount="indefinite"/><rect x="-16" y="-5" width="16" height="10" rx="5" fill="${col||"#9fd36a"}" stroke="#4f7a28"/><rect x="1" y="-5" width="16" height="10" rx="5" fill="${col||"#9fd36a"}" stroke="#4f7a28"/></g></g>${lab?fT(x,y+18,lab,6.4,"#f3cd8a","middle",800,22):""}`;
const zBubbles=(x,y,w,h,n,col)=>Array.from({length:n||10},(_,i)=>`<circle cx="${x+((i*37)%100)/100*w}" cy="${y+h}" r="${1+(i%3)*.7}" fill="${col||"rgba(255,255,255,.75)"}"><animate attributeName="cy" from="${y+h}" to="${y}" dur="${1.6+(i%4)*.5}s" begin="${-i*.27}s" repeatCount="indefinite"/></circle>`).join("");
const zGas=(x,y,lab,col,sub)=>`<g transform="translate(${x} ${y})"><circle r="30" fill="${col}" opacity=".92"/><circle r="30" fill="none" stroke="rgba(255,255,255,.5)"/>${fT(0,2,lab,13,"#fff","middle",900)}${sub?fT(0,15,sub,6.2,"#fff4dc","middle",700,16):""}</g>`;
const zGauge=(x,y,val,max,lab)=>{ const a=Math.PI*(1-val/max); return `<g transform="translate(${x} ${y})"><path d="M-26 0A26 26 0 0 1 26 0" fill="none" stroke="rgba(255,244,220,.35)" stroke-width="6"/><path d="M-26 0A26 26 0 0 1 ${(Math.cos(a)*26).toFixed(1)} ${(-Math.sin(a)*26).toFixed(1)}" fill="none" stroke="#d4a23a" stroke-width="6"/><path d="M0 0L${(Math.cos(a)*20).toFixed(1)} ${(-Math.sin(a)*20).toFixed(1)}" stroke="#fff" stroke-width="2"/><circle r="3" fill="#fff"/>${fT(0,13,lab,7,"#fff4dc","middle",800)}</g>`; };
const zSkin=(x,y,w,h,col)=>`<g>${Array.from({length:Math.floor(w/9)*Math.floor(h/9)},(_,i)=>{ const cx=x+5+(i%Math.floor(w/9))*9+((i*13)%5), cy=y+5+Math.floor(i/Math.floor(w/9))*9; return `<ellipse cx="${cx}" cy="${cy}" rx="4.4" ry="3" fill="${col||"#4a1236"}" opacity=".9" transform="rotate(${(i*47)%180} ${cx} ${cy})"/>`; }).join("")}</g>`;
const zIce=(x,y)=>`<g transform="translate(${x} ${y})"><rect x="-9" y="-7" width="18" height="14" rx="2" fill="#e6f4fb" stroke="#9fd3f0"/><path d="M-9 -7l4 -4h18l-4 4M13 -11v14l-4 4" fill="#cfe9f6" stroke="#9fd3f0"/>${zBubbles(-8,-34,16,26,5,"rgba(220,240,250,.8)")}</g>`;
const zFlame=(x,y)=>`<path d="M${x} ${y}c-8 -8 -4 -18 0 -24c1 6 7 8 6 16c4 -3 4 -7 3 -10c6 6 4 18 -9 18z" fill="#e0662a"><animate attributeName="opacity" values="1;.7;1" dur=".8s" repeatCount="indefinite"/></path>`;
const zDrop=(x,y,col)=>`<path d="M${x} ${y-8}C${x+5} ${y-2} ${x+5} ${y+4} ${x} ${y+4}C${x-5} ${y+4} ${x-5} ${y-2} ${x} ${y-8}Z" fill="${col}"/>`;
const zShield=(x,y,lab)=>`<g transform="translate(${x} ${y})"><path d="M0 -22L18 -15V0C18 12 9 19 0 23C-9 19 -18 12 -18 0V-15Z" fill="#2e6aa0" stroke="#bfe3f5" stroke-width="1.5"/>${fT(0,4,lab||"SO₂",9,"#fff","middle",900)}</g>`;
const zCross=(x,y,inner,r)=>{ r=r||14; return `<g>${inner}<path d="M${x-r} ${y-r}L${x+r} ${y+r}M${x+r} ${y-r}L${x-r} ${y+r}" stroke="#e0505a" stroke-width="3" stroke-linecap="round"/></g>`; };

FILMS.push(
/* ===================== FERMENTATIONS & MACERATIONS COMPARED ===================== */
{id:"fermmac",sec:"c",ch:"vin",ic:"order",nw:1,t:I3("Fermentazioni e macerazioni a confronto","Fermentations et macérations : le comparateur","Fermentations and macerations compared"),s:[
 {h:I3("Due famiglie di processi","Deux familles de processus","Two families of processes"),
  c:I3("In cantina si parla continuamente di fermentazioni e di macerazioni, e spesso si confondono. In questo video le mettiamo tutte a confronto: la fermentazione alcolica, la malolattica, la rifermentazione in bottiglia e i vini frizzanti, poi le macerazioni pellicolare, a freddo, classica, finale, a caldo, carbonica e semicarbonica. Per ognuna vediamo chi lavora, quando interviene e perché.",
   "Au chai, on parle sans cesse de fermentations et de macérations, et on les confond souvent. Dans cette vidéo, on les compare toutes : la fermentation alcoolique, la malolactique, la prise de mousse en bouteille et les vins perlants, puis les macérations pelliculaire, à froid, classique, finale, à chaud, carbonique et semi-carbonique. Pour chacune, on voit qui travaille, à quel moment elle intervient et pourquoi.",
   "In the winery people talk constantly about fermentations and macerations, and they are often confused. In this video we compare them all: alcoholic fermentation, malolactic conversion, second fermentation in bottle and semi-sparkling wines, then skin-contact, cold, classic, post-fermentation, hot, carbonic and semi-carbonic maceration. For each one we see who does the work, when it happens and why."),
  v:()=>fSvg(`${fD(.1,xBox(18,30,136,26,w3("FERMENTAZIONI","FERMENTATIONS","FERMENTATIONS"),"rgba(212,162,58,.45)"))}${fD(.2,xBox(166,30,136,26,w3("MACERAZIONI","MACÉRATIONS","MACERATIONS"),"rgba(163,38,79,.55)"))}
   ${[w3("alcolica","alcoolique","alcoholic"),w3("malolattica","malolactique","malolactic"),w3("in bottiglia","en bouteille","in bottle"),w3("frizzante","perlant","semi-sparkling")].map((s,i)=>fD(.5+i*.3,fChip(86,76+i*24,s))).join("")}
   ${[w3("pellicolare","pelliculaire","skin contact"),w3("a freddo","à froid","cold soak"),w3("classica e finale","classique et finale","classic and post-ferment"),w3("a caldo","à chaud","hot"),w3("carbonica e semicarbonica","carbonique et semi-carbonique","carbonic and semi-carbonic")].map((s,i)=>fD(.7+i*.3,fChip(234,72+i*22,s,"rgba(110,22,48,.85)"))).join("")}`)},
 {h:I3("Fermentazione o macerazione: la differenza","Fermentation ou macération : la différence","Fermentation or maceration: the difference"),
  c:I3("Una fermentazione è una trasformazione: degli esseri viventi, lieviti o batteri, mangiano una sostanza e ne producono di nuove. Lo zucchero diventa alcol e anidride carbonica, l'acido malico diventa acido lattico. Una macerazione invece è un'estrazione: il succo o il vino resta a contatto con le parti solide dell'uva, bucce, vinaccioli e a volte raspi, e ne scioglie colore, tannini e aromi. Niente si trasforma, qualcosa passa dal solido al liquido, come le foglie di tè nell'acqua.",
   "Une fermentation est une transformation : des êtres vivants, levures ou bactéries, consomment une substance et en produisent de nouvelles. Le sucre devient alcool et gaz carbonique, l'acide malique devient acide lactique. Une macération, elle, est une extraction : le jus ou le vin reste en contact avec les parties solides du raisin, pellicules, pépins et parfois rafles, et en dissout la couleur, les tanins et les arômes. Rien ne se transforme, quelque chose passe du solide au liquide, comme les feuilles de thé dans l'eau.",
   "A fermentation is a transformation: living organisms, yeasts or bacteria, consume one substance and produce new ones. Sugar becomes alcohol and carbon dioxide, malic acid becomes lactic acid. A maceration, on the other hand, is an extraction: the juice or wine stays in contact with the solid parts of the grape, skins, seeds and sometimes stems, and dissolves their colour, tannins and aromas. Nothing is transformed, something passes from solid to liquid, like tea leaves in water."),
  v:()=>fSvg(`${xLab(20,26,w3("fermentazione = trasformazione","fermentation = transformation","fermentation = transformation"))}${fD(.2,xMol(46,64,w3("zucchero","sucre","sugar"),"#c9a46a"))}${fD(.5,zYeastBig(100,64,.8))}${fD(.8,fArrow("M118 64H148",null,1))}${fD(1.1,xMol(176,64,w3("alcol","alcool","alcohol"),"#a3264f"))}${fD(1.3,xMol(232,64,"CO₂","#2e6aa0"))}
   ${xLab(20,112,w3("macerazione = estrazione","macération = extraction","maceration = extraction"))}${fD(1.6,`<rect x="40" y="122" width="70" height="62" rx="6" fill="rgba(255,248,232,.12)" stroke="#e8dccf"/><rect x="42" y="136" width="66" height="46" rx="4" fill="#7a1d3a" opacity="0"><animate attributeName="opacity" from="0" to=".85" begin="2s" dur="4s" fill="freeze"/></rect>`+zSkin(44,150,62,30))}${fD(1.9,fCall(108,160,196,140,w3("colore · tannini · aromi","couleur · tanins · arômes","colour · tannins · aromas")))}${fD(2.5,fChip(232,176,w3("come il tè nell'acqua","comme le thé dans l'eau","like tea in water"),"rgba(110,22,48,.85)"))}`)},
 {h:I3("Dove intervengono lungo la vinificazione","Où elles interviennent dans la vinification","Where they happen in winemaking"),
  c:I3("Mettiamo tutto su una linea del tempo. Prima della fermentazione si collocano la macerazione pellicolare dei bianchi e la macerazione a freddo dei rossi. Durante la fermentazione alcolica avviene la macerazione classica dei rossi. Subito dopo può seguire una macerazione finale, prima della svinatura. Poi arriva la malolattica, e per gli spumanti, molto più tardi, la seconda fermentazione in bottiglia.",
   "Mettons tout sur une ligne du temps. Avant la fermentation se placent la macération pelliculaire des blancs et la macération à froid des rouges. Pendant la fermentation alcoolique a lieu la macération classique des rouges. Juste après peut suivre une macération finale, avant l'écoulage. Puis vient la malolactique et, pour les effervescents, beaucoup plus tard, la prise de mousse en bouteille.",
   "Let's put everything on a timeline. Before fermentation come skin contact for whites and cold soak for reds. During alcoholic fermentation the classic red maceration takes place. Right after, a post-fermentation maceration may follow, before draining off. Then comes malolactic conversion and, for sparkling wines, much later, the second fermentation in bottle."),
  v:()=>fSvg(zTL([[1,1,w3("pellicolare","pelliculaire","skin contact"),"#c9a46a",0],[1,1,w3("a freddo","à froid","cold soak"),"#2e6aa0",1],[2,2,w3("classica","classique","classic"),"#a3264f",2],[2,2,w3("FA: lieviti","FA : levures","AF: yeasts"),"#7a5a10",3],[3,3,w3("finale","finale","post-ferm."),"#6e1630",0],[4,4,w3("malolattica: batteri","malo : bactéries","MLF: bacteria"),"#4f7a28",1],[5,6,w3("2ª ferm. in bottiglia","prise de mousse","2nd ferm. in bottle"),"#b8733a",0]],{hi:[1,2,4]})+fD(.1,xLab(24,26,w3("macerazioni sopra · fermentazioni sotto","macérations en haut · fermentations en bas","macerations above · fermentations below"))))},
 {h:I3("La fermentazione alcolica: lo zucchero diventa vino","La fermentation alcoolique : le sucre devient vin","Alcoholic fermentation: sugar becomes wine"),
  c:I3("È la fermentazione fondamentale, quella che trasforma il mosto in vino. I lieviti consumano gli zuccheri dell'uva, glucosio e fruttosio, e producono alcol etilico, anidride carbonica e calore. Servono circa 17 grammi di zucchero per ottenere un grado di alcol. Nascono anche sostanze secondarie preziose: il glicerolo, che dà morbidezza, e gli esteri, che portano aromi fruttati.",
   "C'est la fermentation fondamentale, celle qui transforme le moût en vin. Les levures consomment les sucres du raisin, glucose et fructose, et produisent de l'alcool éthylique, du gaz carbonique et de la chaleur. Il faut environ 17 grammes de sucre pour obtenir un degré d'alcool. Naissent aussi des substances secondaires précieuses : le glycérol, qui apporte du gras, et les esters, qui apportent des arômes fruités.",
   "This is the fundamental fermentation, the one that turns must into wine. Yeasts consume the grape sugars, glucose and fructose, and produce ethyl alcohol, carbon dioxide and heat. About 17 grams of sugar are needed for one degree of alcohol. Valuable by-products appear too: glycerol, which adds smoothness, and esters, which bring fruity aromas."),
  v:()=>fSvg(`${fTank(30,46,90,124,{col:"#e9d27a",lv:.8})}${zBubbles(38,70,74,90,14)}${fD(.3,zYeastBig(60,120,.6)+zYeastBig(92,104,.5))}${fD(.6,xBox(140,40,164,24,w3("zuccheri → alcol + CO₂ + calore","sucres → alcool + CO₂ + chaleur","sugars → alcohol + CO₂ + heat"),"rgba(212,162,58,.45)"))}${fD(1.1,xBoxD(140,74,164,24,w3("≈ 17 g/L di zucchero = 1% vol","≈ 17 g/L de sucre = 1 % vol.","≈ 17 g/L sugar = 1% abv")))}${fD(1.6,fChip(176,120,w3("glicerolo: morbidezza","glycérol : gras","glycerol: smoothness"),"rgba(110,22,48,.85)"))}${fD(1.9,fChip(176,146,w3("esteri: frutta","esters : fruits","esters: fruit"),"rgba(110,22,48,.85)"))}${fD(2.2,fThermo(286,112,"",.6))}`)},
 {h:I3("I lieviti: chi lavora davvero","Les levures : qui travaille vraiment","Yeasts: who really does the work"),
  c:I3("Il protagonista è Saccharomyces cerevisiae, il lievito del vino, che resiste all'alcol e porta la fermentazione fino alla fine. All'inizio però lavorano anche lieviti indigeni non-Saccharomyces, presenti sulle bucce e in cantina: Hanseniaspora, detta anche Kloeckera apiculata, Candida, Pichia, Metschnikowia pulcherrima e Torulaspora delbrueckii. Danno complessità aromatica ma muoiono verso i quattro o cinque gradi di alcol, e Saccharomyces prende il sopravvento.",
   "Le protagoniste est Saccharomyces cerevisiae, la levure du vin, qui résiste à l'alcool et mène la fermentation jusqu'au bout. Au début, pourtant, travaillent aussi des levures indigènes non-Saccharomyces, présentes sur les pellicules et au chai : Hanseniaspora, aussi appelée Kloeckera apiculata, Candida, Pichia, Metschnikowia pulcherrima et Torulaspora delbrueckii. Elles apportent de la complexité aromatique mais meurent vers quatre ou cinq degrés d'alcool, et Saccharomyces prend le dessus.",
   "The star is Saccharomyces cerevisiae, the wine yeast, which tolerates alcohol and carries fermentation through to the end. At the start, though, indigenous non-Saccharomyces yeasts also work, present on the skins and in the winery: Hanseniaspora, also called Kloeckera apiculata, Candida, Pichia, Metschnikowia pulcherrima and Torulaspora delbrueckii. They add aromatic complexity but die off at around four or five degrees of alcohol, and Saccharomyces takes over."),
  v:()=>fSvg(`${fD(.1,zYeastBig(70,70,1.6,"Saccharomyces cerevisiae"))}${fD(.4,fChip(70,158,w3("resiste all'alcol","résiste à l'alcool","alcohol-tolerant"),"rgba(46,125,79,.85)"))}
   ${xLab(160,26,w3("lieviti indigeni","levures indigènes","indigenous yeasts"))}${xLab(160,36,"non-Saccharomyces")}${["Hanseniaspora (Kloeckera)","Candida","Pichia","Metschnikowia pulcherrima","Torulaspora delbrueckii"].map((s,i)=>fD(.7+i*.25,fYeast(170,46+i*18)+fT(184,49+i*18,s,7,"#fff4dc","start",700))).join("")}${fD(2.2,xBoxD(156,148,152,26,w3("muoiono verso 4-5% vol","meurent vers 4-5 % vol.","die off around 4-5% abv")))}`)},
 {h:I3("Lieviti indigeni o selezionati","Levures indigènes ou sélectionnées","Ambient or cultured yeasts"),
  c:I3("Il produttore può lasciare lavorare i lieviti indigeni, detti anche spontanei o ambientali: la fermentazione è più lenta e meno prevedibile, ma spesso più complessa. Oppure può aggiungere lieviti selezionati, ceppi di Saccharomyces cerevisiae scelti per la loro affidabilità, per partire in fretta, finire a secco e ottenere uno stile preciso. Esiste anche un lievito nemico: Brettanomyces bruxellensis, che dà odori di stalla, cuoio e cerotto.",
   "Le producteur peut laisser travailler les levures indigènes, dites aussi spontanées ou naturelles : la fermentation est plus lente et moins prévisible, mais souvent plus complexe. Ou bien il peut ajouter des levures sélectionnées, des souches de Saccharomyces cerevisiae choisies pour leur fiabilité, pour démarrer vite, finir sec et obtenir un style précis. Il existe aussi une levure ennemie : Brettanomyces bruxellensis, qui donne des odeurs d'écurie, de cuir et de pansement.",
   "The producer can let the ambient yeasts work, also called wild or indigenous: fermentation is slower and less predictable, but often more complex. Or cultured yeasts can be added, strains of Saccharomyces cerevisiae chosen for their reliability, to start quickly, finish dry and achieve a precise style. There is also an enemy yeast: Brettanomyces bruxellensis, which gives smells of farmyard, leather and sticking plaster."),
  v:()=>fSvg(`${zTbl(10,26,[70,116,114],[w3("lieviti","levures","yeasts"),w3("pro","atouts","pros"),w3("contro","limites","cons")],[[w3("indigeni","indigènes","ambient"),w3("complessità, carattere del luogo","complexité, typicité du lieu","complexity, sense of place"),w3("lenti, rischio di arresto","lentes, risque d'arrêt","slow, risk of stopping")],[w3("selezionati","sélectionnées","cultured"),w3("affidabili, veloci, stile preciso","fiables, rapides, style précis","reliable, fast, precise style"),w3("meno complessità","moins de complexité","less complexity")]],{sz:8})}${fD(1.6,zCross(60,156,zYeastBig(60,156,.7)))}${fD(1.8,fT(84,150,"Brettanomyces bruxellensis",7.5,"#f3cd8a","start",800))}${fD(2.1,fT(84,164,w3("stalla · cuoio · cerotto","écurie · cuir · pansement","farmyard · leather · plaster"),7,"#fff4dc","start",700))}`)},
 {h:I3("Temperatura e fine della fermentazione","Température et fin de fermentation","Temperature and the end of fermentation"),
  c:I3("La temperatura guida lo stile. I bianchi e i rosati fermentano al fresco, tra 12 e 22 gradi, per conservare gli aromi fruttati. I rossi fermentano più caldi, tra 20 e 32 gradi, per estrarre colore e tannini. Sopra i 35 gradi circa i lieviti muoiono e la fermentazione si blocca. La fermentazione finisce quando lo zucchero è esaurito, e il vino è secco, oppure quando il produttore la ferma per lasciare zucchero residuo, con il freddo, l'anidride solforosa o la filtrazione.",
   "La température guide le style. Les blancs et les rosés fermentent au frais, entre 12 et 22 degrés, pour garder les arômes fruités. Les rouges fermentent plus chaud, entre 20 et 32 degrés, pour extraire la couleur et les tanins. Au-delà de 35 degrés environ, les levures meurent et la fermentation s'arrête. Elle se termine quand le sucre est épuisé, et le vin est sec, ou quand le producteur l'arrête pour garder du sucre résiduel, par le froid, le dioxyde de soufre ou la filtration.",
   "Temperature drives the style. Whites and rosés ferment cool, between 12 and 22 degrees, to keep fruity aromas. Reds ferment warmer, between 20 and 32 degrees, to extract colour and tannin. Above about 35 degrees the yeasts die and fermentation sticks. It ends when the sugar runs out, and the wine is dry, or when the producer stops it to keep residual sugar, using cold, sulfur dioxide or filtration."),
  v:()=>fSvg(`${fD(.1,fThermo(50,50,"12-22°C",.35,"#5fa0d8"))}${fD(.2,fT(55,140,w3("bianchi · rosati","blancs · rosés","whites · rosés"),7.5,"#fff4dc","middle",800))}${fD(.5,fThermo(130,50,"20-32°C",.65))}${fD(.6,fT(135,140,w3("rossi","rouges","reds"),7.5,"#fff4dc","middle",800))}${fD(.9,fThermo(210,50,">35°C",.95,"#e0505a"))}${fD(1,fT(215,140,w3("lieviti morti","levures mortes","yeasts die"),7.5,"#ffb3b8","middle",800))}${fD(1.5,xBoxD(40,158,240,30,w3("Stop: freddo · SO₂ · filtrazione → zucchero residuo","Arrêt : froid · SO₂ · filtration → sucre résiduel","Stop: cold · SO₂ · filtration → residual sugar")))}`)},
 {h:I3("L'anidride solforosa prima della fermentazione","Le dioxyde de soufre avant la fermentation","Sulfur dioxide before fermentation"),
  c:I3("Già alla pigiatura il produttore aggiunge spesso un po' di anidride solforosa. Protegge il mosto dall'ossidazione, frena i batteri e i lieviti indesiderati, e lascia lavorare Saccharomyces, che la tollera meglio. Ne basta poco: troppa ritarderebbe la fermentazione e bloccherebbe più tardi la malolattica.",
   "Dès le foulage, le producteur ajoute souvent un peu de dioxyde de soufre. Il protège le moût de l'oxydation, freine les bactéries et les levures indésirables, et laisse travailler Saccharomyces, qui le tolère mieux. Il en faut peu : trop retarderait la fermentation et bloquerait plus tard la malolactique.",
   "From crushing onwards, the producer often adds a little sulfur dioxide. It protects the must from oxidation, holds back unwanted bacteria and yeasts, and lets Saccharomyces work, as it tolerates SO₂ better. A little is enough: too much would delay fermentation and later block malolactic conversion."),
  v:()=>fSvg(`${fTank(40,50,90,120,{col:"#e9d27a",lv:.75})}${fD(.2,zShield(85,40))}${fD(.6,zCross(170,60,fBug(170,60,"#9fd36a")))}${fD(.8,fT(196,63,w3("batteri","bactéries","bacteria"),7.5,"#fff4dc","start",800))}${fD(1,zCross(170,98,fYeast(170,98)))}${fD(1.2,fT(196,101,w3("lieviti indesiderati","levures indésirables","unwanted yeasts"),7.5,"#fff4dc","start",800))}${fD(1.4,fYeast(170,136)+fT(196,139,w3("Saccharomyces: tollera","Saccharomyces : tolère","Saccharomyces: tolerates"),7.5,"#9fe3b0","start",800))}${fD(1.9,fChip(240,178,w3("antiossidante + antisettico","antioxydant + antiseptique","antioxidant + antiseptic"),"rgba(46,106,160,.9)"))}`)},
 {h:I3("La fermentazione malolattica: i batteri lattici","La fermentation malolactique : les bactéries lactiques","Malolactic conversion: the lactic bacteria"),
  c:I3("Seconda fermentazione del vino, ma qui lavorano dei batteri, non dei lieviti. Il principale è Oenococcus oeni, affiancato a volte da Lactobacillus e Pediococcus. Trasformano l'acido malico, aspro come una mela verde, in acido lattico, più morbido, e liberano un po' di anidride carbonica. Avviene di solito dopo la fermentazione alcolica, a circa 18-22 gradi, con poca anidride solforosa. Lo zucchero non c'entra: il grado alcolico non cambia.",
   "Deuxième fermentation du vin, mais ici ce sont des bactéries qui travaillent, pas des levures. La principale est Oenococcus oeni, parfois accompagnée de Lactobacillus et de Pediococcus. Elles transforment l'acide malique, vif comme une pomme verte, en acide lactique, plus doux, et libèrent un peu de gaz carbonique. Elle a lieu en général après la fermentation alcoolique, vers 18-22 degrés, avec peu de dioxyde de soufre. Le sucre n'y est pour rien : le degré d'alcool ne change pas.",
   "The wine's second fermentation, but here bacteria do the work, not yeasts. The main one is Oenococcus oeni, sometimes joined by Lactobacillus and Pediococcus. They turn malic acid, tart like a green apple, into lactic acid, which is softer, and release a little carbon dioxide. It usually happens after alcoholic fermentation, at about 18-22 degrees, with little sulfur dioxide. Sugar plays no part: the alcohol level does not change."),
  v:()=>fSvg(`${fD(.1,xMol(52,80,w3("acido malico","acide malique","malic acid"),"#5e8c31",w3("mela verde","pomme verte","green apple")))}${fD(.4,zBactBig(150,40,null,"Oenococcus oeni"))}${fD(.7,zBactBig(112,112,"#c7e39a","Lactobacillus")+zBactBig(160,112,"#c7e39a","Pediococcus"))}${fD(1,fArrow("M80 80H200",null,1))}${fD(1.4,xMol(240,80,w3("acido lattico","acide lactique","lactic acid"),"#c9a46a",w3("latte","lait","milk")))}${fD(1.8,fChip(240,124,"+ CO₂"))}${fD(2.1,fChip(160,166,w3("18-22°C · poco SO₂ · alcol invariato","18-22 °C · peu de SO₂ · alcool inchangé","18-22°C · little SO₂ · alcohol unchanged"),"rgba(46,125,79,.85)"))}`)},
 {h:I3("Malolattica: sì o no, e perché","Malolactique : oui ou non, et pourquoi","Malolactic: yes or no, and why"),
  c:I3("Quasi tutti i rossi la fanno: diventano più morbidi e più stabili in bottiglia. Molti Chardonnay la fanno per avere più rotondità e le note di burro del diacetile. I bianchi aromatici e freschi, come Riesling e Sauvignon Blanc, di solito la evitano, per conservare l'acidità e gli aromi primari. Per bloccarla si usa l'anidride solforosa, si tiene il vino al freddo o lo si filtra per eliminare i batteri.",
   "Presque tous les rouges la font : ils deviennent plus souples et plus stables en bouteille. Beaucoup de chardonnays la font pour gagner en rondeur et en notes beurrées, dues au diacétyle. Les blancs aromatiques et vifs, comme le riesling et le sauvignon blanc, l'évitent en général, pour garder l'acidité et les arômes primaires. Pour la bloquer, on utilise le dioxyde de soufre, on garde le vin au froid ou on le filtre pour éliminer les bactéries.",
   "Almost all reds go through it: they become softer and more stable in bottle. Many Chardonnays do it for more roundness and the buttery notes of diacetyl. Aromatic, crisp whites such as Riesling and Sauvignon Blanc usually avoid it, to keep their acidity and primary aromas. To block it, producers use sulfur dioxide, keep the wine cold or filter it to remove the bacteria."),
  v:()=>fSvg(`${zTbl(14,28,[92,200],[w3("vino","vin","wine"),w3("malolattica","malolactique","malolactic")],[[w3("quasi tutti i rossi","presque tous les rouges","almost all reds"),w3("sì: più morbidi, stabili","oui : plus souples, stables","yes: softer, stable")],["Chardonnay",w3("spesso: rotondità, burro (diacetile)","souvent : rondeur, beurre (diacétyle)","often: roundness, butter (diacetyl)")],["Riesling · Sauvignon Blanc",w3("di solito no: acidità e frutto","en général non : acidité et fruit","usually not: acidity and fruit")]],{sz:7})}${fD(1.6,xBoxD(30,140,260,30,w3("Bloccarla: SO₂ · freddo · filtrazione","La bloquer : SO₂ · froid · filtration","Block it: SO₂ · cold · filtration")))}`)},
 {h:I3("La rifermentazione in bottiglia","La prise de mousse en bouteille","Second fermentation in bottle"),
  c:I3("Per gli spumanti di metodo tradizionale, come lo Champagne, si fa una seconda fermentazione alcolica dentro la bottiglia chiusa. Al vino base si aggiunge il liqueur de tirage: vino, circa 24 grammi di zucchero per litro, lieviti selezionati resistenti all'alcol e alla pressione, spesso del ceppo detto bayanus, e un coadiuvante per il remuage. La bottiglia si chiude con un tappo a corona. I lieviti producono circa un grado e mezzo di alcol in più e l'anidride carbonica, che non può uscire, si scioglie nel vino: circa 6 atmosfere.",
   "Pour les effervescents de méthode traditionnelle, comme le champagne, on fait une deuxième fermentation alcoolique dans la bouteille fermée. Au vin de base on ajoute la liqueur de tirage : du vin, environ 24 grammes de sucre par litre, des levures sélectionnées résistantes à l'alcool et à la pression, souvent de la souche dite bayanus, et un adjuvant de remuage. La bouteille est fermée par une capsule. Les levures produisent environ un degré et demi d'alcool en plus, et le gaz carbonique, qui ne peut pas s'échapper, se dissout dans le vin : environ 6 atmosphères.",
   "For traditional-method sparkling wines such as Champagne, a second alcoholic fermentation takes place inside the sealed bottle. The liqueur de tirage is added to the base wine: wine, about 24 grams of sugar per litre, selected yeasts that tolerate alcohol and pressure, often of the strain known as bayanus, and a riddling aid. The bottle is closed with a crown cap. The yeasts produce about one and a half degrees of extra alcohol, and the carbon dioxide, which cannot escape, dissolves in the wine: about 6 atmospheres."),
  v:()=>fSvg(`${fD(.1,fBottle(70,120,{col:"#e9d27a",cork:0}))}${fD(.3,zBubbles(62,80,16,56,10))}${fD(.6,xSheet(120,30,184,[["tirage",w3("vino base + liqueur","vin de base + liqueur","base wine + liqueur")],[w3("zucchero","sucre","sugar"),"≈ 24 g/L"],[w3("lieviti","levures","yeasts"),"S. cerevisiae (bayanus)"],[w3("chiusura","bouchage","closure"),w3("tappo a corona","capsule","crown cap")],[w3("risultato","résultat","result"),"+1,2-1,5% vol · CO₂"]],.6))}${fD(2,zGauge(212,160,6,8,"≈ 6 atm"))}`)},
 {h:I3("Dopo la presa di spuma: l'autolisi","Après la prise de mousse : l'autolyse","After the second fermentation: autolysis"),
  c:I3("Finita la fermentazione, i lieviti morti si depositano: sono le fecce, o lieviti esausti. Durante il lungo affinamento sui lieviti si decompongono lentamente, è l'autolisi, e cedono al vino aromi di pane, brioche e biscotto, oltre a una spuma più fine. Altri metodi: nel metodo Charmat la seconda fermentazione avviene in autoclave, una vasca pressurizzata, come per il Prosecco; nel metodo ancestrale c'è una sola fermentazione, che finisce in bottiglia.",
   "Une fois la fermentation finie, les levures mortes se déposent : ce sont les lies. Pendant le long vieillissement sur lies, elles se décomposent lentement, c'est l'autolyse, et donnent au vin des arômes de pain, de brioche et de biscuit, ainsi qu'une mousse plus fine. Autres méthodes : dans la méthode en cuve close, ou Charmat, la prise de mousse a lieu dans une cuve sous pression, comme pour le prosecco ; dans la méthode ancestrale, il n'y a qu'une seule fermentation, qui se termine en bouteille.",
   "Once fermentation is over, the dead yeasts settle: these are the lees. During long ageing on the lees they slowly break down, this is autolysis, and give the wine aromas of bread, brioche and biscuit, plus a finer mousse. Other methods: in the tank method, or Charmat, the second fermentation happens in a pressurised tank, as for Prosecco; in the ancestral method there is only one fermentation, which finishes in the bottle."),
  v:()=>fSvg(`${fD(.1,fBottle(56,110,{col:"#e9d27a",rot:-80}))}${fD(.4,`<ellipse cx="96" cy="118" rx="22" ry="4" fill="#d9c58c" opacity=".9"/>`)}${fD(.7,fCall(96,118,110,60,w3("fecce: autolisi","lies : autolyse","lees: autolysis")))}${fD(1.1,fChip(110,150,w3("pane · brioche · biscotto","pain · brioche · biscuit","bread · brioche · biscuit"),"rgba(110,22,48,.85)"))}${zTbl(170,30,[56,82],[w3("metodo","méthode","method"),w3("2ª fermentazione","prise de mousse","2nd ferm.")],[[w3("tradizionale","traditionnelle","traditional"),w3("in bottiglia","en bouteille","in bottle")],["Charmat",w3("in autoclave","en cuve close","in tank")],[w3("ancestrale","ancestrale","ancestral"),w3("una sola, finisce in bottiglia","une seule, finie en bouteille","just one, ends in bottle")]],{sz:6.4,d0:1.5})}`)},
 {h:I3("I vini frizzanti e perlanti","Les vins perlants et pétillants","Semi-sparkling and lightly sparkling wines"),
  c:I3("Tra il vino fermo e lo spumante esistono i vini con poca effervescenza. Un vino perlante ha solo un leggero pizzicore; un frizzante arriva fino a circa 2,5 bar, mentre uno spumante supera i 3 bar. Le bollicine possono venire dall'anidride carbonica della fermentazione trattenuta nel vino, imbottigliando al freddo e senza travasi, come nel Muscadet sur lie; da una breve rifermentazione in autoclave, come nel Prosecco frizzante o nel Moscato d'Asti; oppure da un'aggiunta di anidride carbonica, la gassificazione, frequente nel Vinho Verde.",
   "Entre le vin tranquille et l'effervescent, il existe des vins peu gazeux. Un vin perlant n'a qu'un léger picotement ; un pétillant monte jusqu'à environ 2,5 bars, alors qu'un mousseux dépasse 3 bars. Les bulles peuvent venir du gaz carbonique de la fermentation gardé dans le vin, en mettant en bouteille au froid et sans soutirage, comme le muscadet sur lie ; d'une courte refermentation en cuve close, comme le prosecco frizzante ou le moscato d'Asti ; ou d'un ajout de gaz carbonique, la gazéification, fréquente pour le vinho verde.",
   "Between still and sparkling wine there are wines with just a little fizz. A lightly sparkling wine has only a slight prickle; a semi-sparkling wine reaches about 2.5 bar, while a fully sparkling wine exceeds 3 bar. The bubbles can come from fermentation carbon dioxide kept in the wine, by bottling cold and without racking, as in Muscadet sur lie; from a short refermentation in a pressurised tank, as in Prosecco Frizzante or Moscato d'Asti; or from adding carbon dioxide, carbonation, common for Vinho Verde."),
  v:()=>fSvg(`${[[0,w3("fermo","tranquille","still"),"0"],[1,w3("perlante","perlant","light prickle"),"< 1 bar"],[2,w3("frizzante","pétillant","semi-sparkling"),"1-2,5 bar"],[3,w3("spumante","mousseux","sparkling"),"> 3 bar"]].map(([i,l,p])=>{ const x=50+i*74; return fD(.2+i*.35,fGlass(x,86,"#efe1a0",1.3)+zBubbles(x-10,56,20,30,i*5)+fT(x,136,l,7.5,"#fff4dc","middle",800)+fT(x,148,p,7,"#f3cd8a","middle",700)); }).join("")}${fD(1.8,fChip(160,172,w3("CO₂ trattenuta · autoclave · gassificazione","CO₂ gardé · cuve close · gazéification","CO₂ kept · tank · carbonation"),"rgba(110,22,48,.85)"))}`)},
 {h:I3("Le fermentazioni a confronto","Les fermentations comparées","The fermentations compared"),
  c:I3("Riassumiamo. La fermentazione alcolica è fatta dai lieviti, trasforma lo zucchero in alcol e anidride carbonica e crea il vino. La malolattica è fatta dai batteri lattici, trasforma l'acido malico in acido lattico e ammorbidisce il vino. La rifermentazione in bottiglia è una seconda fermentazione alcolica fatta dai lieviti in bottiglia chiusa: crea le bollicine. Il frizzante trattiene, produce o aggiunge un po' di anidride carbonica.",
   "Résumons. La fermentation alcoolique est faite par les levures, transforme le sucre en alcool et en gaz carbonique, et crée le vin. La malolactique est faite par les bactéries lactiques, transforme l'acide malique en acide lactique et assouplit le vin. La prise de mousse est une deuxième fermentation alcoolique faite par les levures dans la bouteille fermée : elle crée les bulles. Le perlant garde, produit ou reçoit un peu de gaz carbonique.",
   "To sum up. Alcoholic fermentation is done by yeasts, turns sugar into alcohol and carbon dioxide, and creates the wine. Malolactic conversion is done by lactic bacteria, turns malic acid into lactic acid and softens the wine. Second fermentation in bottle is another alcoholic fermentation by yeasts in a sealed bottle: it creates the bubbles. Semi-sparkling wines keep, produce or receive a little carbon dioxide."),
  v:()=>fSvg(zTbl(6,14,[60,70,92,86],[w3("processo","processus","process"),w3("chi","qui","who"),w3("trasforma","transforme","converts"),w3("perché","pourquoi","why")],[[w3("alcolica","alcoolique","alcoholic"),"S. cerevisiae",w3("zucchero → alcol + CO₂","sucre → alcool + CO₂","sugar → alcohol + CO₂"),w3("fare il vino","faire le vin","make wine")],[w3("malolattica","malolactique","malolactic"),"Oenococcus oeni",w3("malico → lattico + CO₂","malique → lactique + CO₂","malic → lactic + CO₂"),w3("morbidezza, stabilità","souplesse, stabilité","softness, stability")],[w3("in bottiglia","prise de mousse","in bottle"),w3("lieviti (bayanus)","levures (bayanus)","yeasts (bayanus)"),w3("zucchero del tirage → CO₂","sucre du tirage → CO₂","tirage sugar → CO₂"),w3("bollicine, autolisi","bulles, autolyse","bubbles, autolysis")],[w3("frizzante","perlant","semi-sparkling"),w3("lieviti o aggiunta","levures ou ajout","yeasts or added"),w3("poca CO₂","un peu de CO₂","a little CO₂"),w3("freschezza, pizzicore","fraîcheur, picotement","freshness, prickle")]],{sz:7}))},
 {h:I3("Che cosa estrae una macerazione","Ce qu'extrait une macération","What a maceration extracts"),
  c:I3("Passiamo alle macerazioni. Nella buccia si trovano gli antociani, i pigmenti rossi, i tannini e molti precursori d'aroma; nei vinaccioli altri tannini, più duri; nei raspi tannini verdi e freschezza. Gli antociani si sciolgono presto, già in acqua; i tannini hanno bisogno di alcol e di tempo. Quattro leve regolano l'estrazione: la durata, la temperatura, il contatto tra liquido e bucce e la presenza di alcol.",
   "Passons aux macérations. Dans la pellicule se trouvent les anthocyanes, les pigments rouges, les tanins et de nombreux précurseurs d'arômes ; dans les pépins, d'autres tanins, plus durs ; dans les rafles, des tanins verts et de la fraîcheur. Les anthocyanes se dissolvent tôt, déjà dans l'eau ; les tanins ont besoin d'alcool et de temps. Quatre leviers règlent l'extraction : la durée, la température, le contact entre le liquide et les pellicules, et la présence d'alcool.",
   "Now the macerations. The skin holds anthocyanins, the red pigments, tannins and many aroma precursors; the seeds hold other, harsher tannins; the stems give green tannins and freshness. Anthocyanins dissolve early, already in water; tannins need alcohol and time. Four levers control extraction: duration, temperature, contact between liquid and skins, and the presence of alcohol."),
  v:()=>fSvg(`${fD(.1,xBerry(70,90,46))}${fD(.5,fCall(30,60,130,30,w3("buccia: antociani, tannini, aromi","pellicule : anthocyanes, tanins, arômes","skin: anthocyanins, tannins, aromas")))}${fD(.9,fCall(70,118,90,170,w3("vinaccioli: tannini duri","pépins : tanins durs","seeds: harsh tannins")))}${fD(1.3,xSide(206,52,104,[w3("durata","durée","time"),w3("temperatura","température","temperature"),w3("contatto","contact","contact"),w3("alcol","alcool","alcohol")],1.4))}`)},
 {h:I3("La macerazione pellicolare dei bianchi","La macération pelliculaire des blancs","Skin contact for white wines"),
  c:I3("Per alcuni bianchi aromatici, come Sauvignon Blanc o Moscato, le uve pigiate restano qualche ora a contatto con le bucce prima della pressatura, di solito da 4 a 24 ore e al freddo. Si estraggono così i precursori d'aroma della buccia: il vino sarà più intenso e più ampio. Il rischio è estrarre troppi fenoli, con amarezza e minore freschezza. Se la macerazione dura giorni o settimane, con la fermentazione sulle bucce, si ottiene un orange wine, o vino macerato.",
   "Pour certains blancs aromatiques, comme le sauvignon blanc ou le muscat, le raisin foulé reste quelques heures en contact avec les pellicules avant le pressurage, en général de 4 à 24 heures et au froid. On extrait ainsi les précurseurs d'arômes de la pellicule : le vin sera plus intense et plus ample. Le risque est d'extraire trop de composés phénoliques, avec de l'amertume et moins de fraîcheur. Si la macération dure des jours ou des semaines, avec la fermentation sur les pellicules, on obtient un vin orange, ou vin de macération.",
   "For some aromatic whites, such as Sauvignon Blanc or Muscat, the crushed grapes stay in contact with the skins for a few hours before pressing, usually 4 to 24 hours and cold. This extracts aroma precursors from the skin: the wine will be more intense and broader. The risk is extracting too many phenolics, with bitterness and less freshness. If maceration lasts days or weeks, with fermentation on the skins, the result is an orange wine, or skin-macerated white."),
  v:()=>fSvg(`${fTank(30,52,96,116,{col:"#efe1a0",lv:.8})}${fD(.2,zSkin(36,120,84,40,"#a8b84a"))}${fD(.5,fThermo(140,60,"5-15°C",.25,"#5fa0d8"))}${fD(.8,xBoxD(170,40,138,26,w3("4-24 ore, prima della pressatura","4-24 heures, avant pressurage","4-24 hours, before pressing")))}${fD(1.2,fChip(238,90,w3("+ aromi · + volume","+ arômes · + volume","+ aroma · + body"),"rgba(46,125,79,.85)"))}${fD(1.5,fChip(238,114,w3("rischio: amaro","risque : amertume","risk: bitterness"),"rgba(176,42,60,.85)"))}${fD(2,fGlass(186,166,"#d98a2a",1)+fT(204,160,w3("giorni → orange wine","jours → vin orange","days → orange wine"),7.5,"#f3cd8a","start",800))}`)},
 {h:I3("La macerazione a freddo prefermentativa","La macération préfermentaire à froid","Cold soak before fermentation"),
  c:I3("Per i rossi, soprattutto il Pinot Noir, le uve pigiate si tengono al freddo, tra 4 e 10 gradi, per alcuni giorni prima della fermentazione. A questa temperatura i lieviti non partono. Si protegge il mosto con un po' di anidride solforosa e con anidride carbonica, spesso sotto forma di ghiaccio secco. In assenza di alcol si estraggono colore e aromi fruttati, ma pochi tannini: il vino sarà più colorato, più fruttato e più morbido.",
   "Pour les rouges, surtout le pinot noir, le raisin foulé est gardé au froid, entre 4 et 10 degrés, pendant quelques jours avant la fermentation. À cette température, les levures ne démarrent pas. On protège le moût avec un peu de dioxyde de soufre et du gaz carbonique, souvent sous forme de neige carbonique. Sans alcool, on extrait la couleur et les arômes fruités, mais peu de tanins : le vin sera plus coloré, plus fruité et plus souple.",
   "For reds, especially Pinot Noir, the crushed grapes are kept cold, between 4 and 10 degrees, for a few days before fermentation. At this temperature the yeasts do not start. The must is protected with a little sulfur dioxide and with carbon dioxide, often as dry ice. Without alcohol, colour and fruity aromas are extracted, but few tannins: the wine will be deeper in colour, fruitier and softer."),
  v:()=>fSvg(`${fTank(40,48,96,120,{col:"#5a1035",lv:.8})}${fD(.2,zSkin(46,100,84,60))}${fD(.4,zIce(70,74)+zIce(104,80))}${fD(.6,fThermo(150,60,"4-10°C",.2,"#5fa0d8"))}${fD(.9,xBoxD(178,40,130,26,w3("qualche giorno, prima della FA","quelques jours, avant la FA","a few days, before AF")))}${fD(1.2,fChip(243,90,w3("ghiaccio secco = CO₂","neige carbonique = CO₂","dry ice = CO₂"),"rgba(46,106,160,.9)"))}${fD(1.5,fChip(243,116,w3("colore + frutto","couleur + fruit","colour + fruit"),"rgba(46,125,79,.85)"))}${fD(1.8,fChip(243,140,w3("pochi tannini","peu de tanins","few tannins"),"rgba(110,22,48,.85)"))}${fD(2.1,fChip(243,170,"Pinot Noir"))}`)},
 {h:I3("La macerazione classica durante la fermentazione","La macération classique pendant la fermentation","Classic maceration during fermentation"),
  c:I3("È la macerazione di tutti i rossi. Mentre i lieviti lavorano, l'anidride carbonica spinge le bucce in alto e forma il cappello. Per estrarre bisogna rimetterlo in contatto con il liquido: con la follatura si spinge giù il cappello, con il rimontaggio si pompa il mosto sopra il cappello, con il délestage si svuota la vasca e la si riempie di nuovo. Più la temperatura sale, più l'estrazione è forte. Prima escono i colori, poi, con l'alcol, i tannini.",
   "C'est la macération de tous les rouges. Pendant que les levures travaillent, le gaz carbonique pousse les pellicules vers le haut et forme le chapeau de marc. Pour extraire, il faut le remettre en contact avec le liquide : par le pigeage, on enfonce le chapeau ; par le remontage, on pompe le moût par-dessus le chapeau ; par le délestage, on vide la cuve puis on la remplit à nouveau. Plus la température monte, plus l'extraction est forte. La couleur sort d'abord, puis, avec l'alcool, les tanins.",
   "This is the maceration of every red wine. While the yeasts work, carbon dioxide pushes the skins to the top, forming the cap. To extract, the cap must be put back in contact with the liquid: punching down pushes it under, pumping over sprays the must over it, and rack and return empties the vat and refills it. The higher the temperature, the stronger the extraction. Colour comes out first, then, with alcohol, the tannins."),
  v:()=>fSvg(`${fTank(30,40,110,134,{col:"#5a1035",lv:.85})}${fD(.2,zSkin(36,60,98,26))}${zBubbles(40,90,90,76,12)}${fD(.5,fChip(85,52,w3("cappello","chapeau","cap")))}${fD(.8,xSide(174,30,134,[w3("follatura: spingere giù","pigeage : enfoncer","punching down"),w3("rimontaggio: pompare sopra","remontage : arroser","pumping over"),w3("délestage: svuotare e riempire","délestage : vider puis remplir","rack and return")],.8))}${fD(1.9,fChip(241,128,"🌡 20-32°C","rgba(176,42,60,.85)"))}${fD(2.2,fChip(241,156,w3("prima colore, poi tannini","d'abord couleur, puis tanins","colour first, then tannins"),"rgba(110,22,48,.85)"))}`)},
 {h:I3("La macerazione finale, dopo la fermentazione","La macération finale, après la fermentation","Post-fermentation maceration"),
  c:I3("Per alcuni grandi rossi da invecchiamento, come a Bordeaux o per il Nebbiolo, il vino resta sulle bucce ancora per una o più settimane dopo la fine della fermentazione, prima della svinatura. In presenza di alcol i tannini continuano a sciogliersi e si legano tra loro in catene più lunghe: il risultato è un vino più strutturato ma con tannini più morbidi e vellutati. La vasca va tenuta piena e protetta dall'ossigeno.",
   "Pour certains grands rouges de garde, comme à Bordeaux ou pour le nebbiolo, le vin reste sur les pellicules encore une ou plusieurs semaines après la fin de la fermentation, avant l'écoulage. En présence d'alcool, les tanins continuent de se dissoudre et se lient entre eux en chaînes plus longues : on obtient un vin plus structuré mais aux tanins plus souples et veloutés. La cuve doit rester pleine et protégée de l'oxygène.",
   "For some great reds made for ageing, as in Bordeaux or for Nebbiolo, the wine stays on the skins for one or more weeks after fermentation ends, before draining off. With alcohol present, tannins keep dissolving and link up into longer chains: the result is a more structured wine with softer, velvety tannins. The vat must be kept full and protected from oxygen."),
  v:()=>fSvg(`${fTank(36,40,100,130,{col:"#3d0f22",lv:.92})}${fD(.2,zSkin(42,110,88,52))}${fD(.5,xBoxD(160,40,148,26,w3("1-4 settimane dopo la FA","1 à 4 semaines après la FA","1-4 weeks after AF")))}${fD(.9,`<g transform="translate(170 96)">${[0,1,2,3,4].map(i=>`<circle cx="${i*12}" cy="0" r="4" fill="#c9a46a"/>`).join("")}</g>`+fT(240,99,w3("tannini in catene","tanins en chaînes","tannins link up"),7,"#fff4dc","start",700,14))}${fD(1.4,fChip(234,128,w3("struttura + tannini vellutati","structure + tanins veloutés","structure + velvety tannins"),"rgba(46,125,79,.85)"))}${fD(1.8,fChip(234,156,"Bordeaux · Nebbiolo"))}`)},
 {h:I3("Le macerazioni a caldo","Les macérations à chaud","Hot macerations"),
  c:I3("Il calore accelera l'estrazione. Nella termovinificazione il mosto viene riscaldato a 60-70 gradi per poco tempo, poi pressato: il succo si colora subito e fermenta senza bucce, dando rossi molto fruttati, morbidi e pronti da bere. Esiste anche la macerazione finale a caldo, a fine fermentazione intorno ai 30-40 gradi, per estrarre di più. Sono tecniche rapide, usate soprattutto per vini da bere giovani.",
   "La chaleur accélère l'extraction. Dans la thermovinification, le moût est chauffé à 60-70 degrés pendant peu de temps, puis pressé : le jus se colore tout de suite et fermente sans pellicules, ce qui donne des rouges très fruités, souples et prêts à boire. Il existe aussi la macération finale à chaud, en fin de fermentation vers 30-40 degrés, pour extraire davantage. Ce sont des techniques rapides, surtout pour des vins à boire jeunes.",
   "Heat speeds up extraction. In thermovinification the must is heated to 60-70 degrees for a short time, then pressed: the juice colours immediately and ferments without skins, giving very fruity, soft reds that are ready to drink. There is also hot post-fermentation maceration, at the end of fermentation around 30-40 degrees, to extract more. These are fast techniques, used mainly for wines to drink young."),
  v:()=>fSvg(`${fTank(40,50,96,116,{col:"#8a1f3e",lv:.8})}${fD(.2,zFlame(78,186)+zFlame(100,186))}${fD(.4,fThermo(150,56,"60-70°C",.9,"#e0505a"))}${fD(.8,fArrow("M170 110H206",null,1))}${fD(1,fBasketPress(242,124))}${fD(1.4,xBoxD(176,30,132,26,w3("termovinificazione","thermovinification","thermovinification")))}${fD(1.8,fChip(240,176,w3("frutto, morbido, da bere giovane","fruité, souple, à boire jeune","fruity, soft, drink young"),"rgba(110,22,48,.85)"))}`)},
 {h:I3("La macerazione carbonica","La macération carbonique","Carbonic maceration"),
  c:I3("Qui si usano grappoli interi e intatti, in una vasca riempita di anidride carbonica e chiusa. Senza ossigeno, dentro ogni acino parte una fermentazione intracellulare: non sono i lieviti a lavorare, ma gli enzimi dell'uva stessa, che producono circa 2 gradi di alcol e aromi particolari. Dopo una o due settimane, verso 30 gradi, gli acini si pressano e i lieviti finiscono la fermentazione. Il vino è colorato, poco tannico, con note di ciliegia, banana, chewing-gum e cannella: è il Beaujolais con il Gamay.",
   "Ici on utilise des grappes entières et intactes, dans une cuve remplie de gaz carbonique et fermée. Sans oxygène, à l'intérieur de chaque baie démarre une fermentation intracellulaire : ce ne sont pas les levures qui travaillent, mais les enzymes du raisin lui-même, qui produisent environ 2 degrés d'alcool et des arômes particuliers. Après une ou deux semaines, vers 30 degrés, les baies sont pressées et les levures finissent la fermentation. Le vin est coloré, peu tannique, avec des notes de cerise, de banane, de bonbon anglais et de cannelle : c'est le Beaujolais avec le gamay.",
   "Here whole, intact bunches are used, in a vat filled with carbon dioxide and sealed. Without oxygen, an intracellular fermentation starts inside each berry: it is not the yeasts at work but the grape's own enzymes, which produce about 2 degrees of alcohol and distinctive aromas. After one or two weeks, at around 30 degrees, the berries are pressed and the yeasts finish the fermentation. The wine is deeply coloured, low in tannin, with notes of cherry, banana, bubblegum and cinnamon: this is Beaujolais with Gamay."),
  v:()=>fSvg(`${fTank(30,40,100,130,{col:"rgba(160,210,240,.25)",lv:.95})}${xCO2(38,62,84,6)}${fD(.4,xBunch(56,96,.9)+xBunch(92,100,.9)+xBunch(74,128,.9))}${fD(.8,xBerry(190,74,30,{ferm:1,colour:1.5}))}${fD(1.1,fCall(214,62,268,40,w3("enzimi, non lieviti","enzymes, pas levures","enzymes, not yeasts")))}${fD(1.4,fChip(190,118,w3("≈ 2% vol nell'acino","≈ 2 % vol. dans la baie","≈ 2% abv inside berry")))}${fD(1.9,fChip(220,148,w3("ciliegia · banana · chewing-gum · cannella","cerise · banane · bonbon · cannelle","cherry · banana · bubblegum · cinnamon"),"rgba(110,22,48,.85)"))}${fD(2.3,fChip(220,174,"Gamay · Beaujolais"))}`)},
 {h:I3("La macerazione semicarbonica","La macération semi-carbonique","Semi-carbonic maceration"),
  c:I3("Variante più semplice e molto diffusa in Beaujolais: la vasca si riempie di grappoli interi, ma senza aggiungere anidride carbonica. Sul fondo, il peso schiaccia una parte degli acini: il succo che esce fermenta con i lieviti e produce anidride carbonica, che sale e copre il resto della vasca. In alto, gli acini interi fanno la fermentazione intracellulare. Ci sono quindi tre zone: succo che fermenta in basso, acini che si rompono in mezzo, grappoli interi sotto la CO₂ in alto.",
   "Variante plus simple et très répandue dans le Beaujolais : la cuve est remplie de grappes entières, mais sans ajout de gaz carbonique. Au fond, le poids écrase une partie des baies : le jus qui s'écoule fermente avec les levures et produit du gaz carbonique, qui monte et couvre le reste de la cuve. En haut, les baies entières font la fermentation intracellulaire. Il y a donc trois zones : du jus qui fermente en bas, des baies qui éclatent au milieu, des grappes entières sous le CO₂ en haut.",
   "A simpler variant, widespread in Beaujolais: the vat is filled with whole bunches, but no carbon dioxide is added. At the bottom, the weight crushes some of the berries: the juice that runs out ferments with yeasts and produces carbon dioxide, which rises and blankets the rest of the vat. At the top, the whole berries undergo intracellular fermentation. So there are three zones: fermenting juice at the bottom, bursting berries in the middle, whole bunches under CO₂ at the top."),
  v:()=>fSvg(`${fTank(60,30,110,150,{col:"#5a1035",lv:.28})}${xCO2(68,50,94,6)}${fD(.3,xBunch(84,66,.7)+xBunch(116,64,.7)+xBunch(148,68,.7)+xBunch(100,96,.7)+xBunch(134,98,.7))}${zBubbles(70,140,90,36,10)}${fD(.6,fYeast(90,160)+fYeast(130,166))}${fD(.9,fCall(170,60,250,40,w3("grappoli interi + CO₂","grappes entières + CO₂","whole bunches + CO₂")))}${fD(1.3,fCall(170,110,250,98,w3("acini che si rompono","baies qui éclatent","bursting berries")))}${fD(1.7,fCall(170,158,250,156,w3("succo + lieviti → CO₂","jus + levures → CO₂","juice + yeasts → CO₂")))}`)},
 {h:I3("Grappolo intero, rosati e altre macerazioni","Vendange entière, rosés et autres macérations","Whole bunches, rosés and other macerations"),
  c:I3("Molti produttori di Pinot Noir in Borgogna o di Syrah nel Rodano mettono una parte di grappoli interi, con i raspi, in una vinificazione classica: i raspi portano freschezza, tannini e aromi speziati, se sono ben maturi. Per i rosati la macerazione è breve: poche ore o un giorno o due prima di separare il mosto, oppure si ricorre al salasso, prelevando un po' di mosto da una vasca di rosso. Con la pressatura diretta il contatto con le bucce è minimo.",
   "Beaucoup de producteurs de pinot noir en Bourgogne ou de syrah dans le Rhône mettent une partie de vendange entière, avec les rafles, dans une vinification classique : les rafles apportent fraîcheur, tanins et arômes épicés, si elles sont bien mûres. Pour les rosés, la macération est courte : quelques heures à un ou deux jours avant de séparer le moût, ou bien on fait une saignée, en prélevant un peu de moût d'une cuve de rouge. Avec le pressurage direct, le contact avec les pellicules est minimal.",
   "Many Pinot Noir producers in Burgundy or Syrah producers in the Rhône include some whole bunches, stems and all, in a classic fermentation: if the stems are ripe they bring freshness, tannin and spicy aromas. For rosés the maceration is short: a few hours to a day or two before separating the must, or the saignée method is used, bleeding some must off a red-wine vat. With direct pressing, skin contact is minimal."),
  v:()=>fSvg(`${fD(.1,xBunch(56,70,1.4))}${fD(.4,fCall(56,56,120,34,w3("raspi: freschezza, spezie","rafles : fraîcheur, épices","stems: freshness, spice")))}${fD(.7,fChip(70,132,w3("Borgogna · Rodano","Bourgogne · Rhône","Burgundy · Rhône")))}${xLab(178,60,w3("rosati","rosés","rosés"))}${[["#f6cfc4",w3("pressatura diretta","pressurage direct","direct press")],["#f09aa0",w3("macerazione breve","macération courte","short maceration")],["#d9586e",w3("salasso","saignée","saignée")]].map(([c,l],i)=>fD(.6+i*.3,fGlass(194+i*50,112,c,1.1)+fT(194+i*50,154,l,6.6,"#fff4dc","middle",700,12))).join("")}`)},
 {h:I3("Le macerazioni a confronto","Les macérations comparées","The macerations compared"),
  c:I3("Ecco il quadro completo. La pellicolare: bianchi, al freddo, poche ore prima della pressatura, per gli aromi. A freddo: rossi, a 4-10 gradi prima della fermentazione, per colore e frutto. Classica: tutti i rossi, durante la fermentazione, per colore e tannini. Finale: dopo la fermentazione, per tannini più fini. A caldo: per estrarre in fretta. Carbonica e semicarbonica: grappoli interi, fermentazione intracellulare, per vini fruttati e poco tannici.",
   "Voici le tableau complet. Pelliculaire : blancs, au froid, quelques heures avant le pressurage, pour les arômes. À froid : rouges, à 4-10 degrés avant la fermentation, pour la couleur et le fruit. Classique : tous les rouges, pendant la fermentation, pour la couleur et les tanins. Finale : après la fermentation, pour des tanins plus fins. À chaud : pour extraire vite. Carbonique et semi-carbonique : grappes entières, fermentation intracellulaire, pour des vins fruités et peu tanniques.",
   "Here is the full picture. Skin contact: whites, cold, a few hours before pressing, for aroma. Cold soak: reds, at 4-10 degrees before fermentation, for colour and fruit. Classic: all reds, during fermentation, for colour and tannin. Post-fermentation: after fermentation, for finer tannins. Hot: to extract quickly. Carbonic and semi-carbonic: whole bunches, intracellular fermentation, for fruity, low-tannin wines."),
  v:()=>fSvg(zTbl(6,14,[66,70,58,114],[w3("macerazione","macération","maceration"),w3("quando","quand","when"),"T°",w3("perché","pourquoi","why")],[[w3("pellicolare","pelliculaire","skin contact"),w3("prima della pressatura","avant pressurage","before pressing"),"5-15°C",w3("aromi dei bianchi","arômes des blancs","white-wine aroma")],[w3("a freddo","à froid","cold soak"),w3("prima della FA","avant la FA","before AF"),"4-10°C",w3("colore, frutto, pochi tannini","couleur, fruit, peu de tanins","colour, fruit, few tannins")],[w3("classica","classique","classic"),w3("durante la FA","pendant la FA","during AF"),"20-32°C",w3("colore e tannini","couleur et tanins","colour and tannin")],[w3("finale","finale","post-ferm."),w3("dopo la FA","après la FA","after AF"),"≈ 25-30°C",w3("tannini più vellutati","tanins plus veloutés","silkier tannins")],[w3("a caldo","à chaud","hot"),w3("prima o a fine FA","avant ou fin de FA","before or end of AF"),"30-70°C",w3("estrazione rapida","extraction rapide","fast extraction")],[w3("carbonica","carbonique","carbonic"),w3("grappoli interi, CO₂","grappes entières, CO₂","whole bunches, CO₂"),"≈ 30°C",w3("frutto, pochi tannini","fruit, peu de tanins","fruit, low tannin")]],{sz:6.6,dd:.3}))},
 {h:I3("Da ricordare","À retenir","Key points"),
  c:I3("Fermentare significa trasformare, grazie a lieviti o batteri. Macerare significa estrarre, grazie al contatto con le bucce. Saccharomyces cerevisiae fa la fermentazione alcolica, Oenococcus oeni la malolattica. L'anidride carbonica nasce dalle fermentazioni e protegge le macerazioni; l'anidride solforosa sceglie chi può lavorare. E nella macerazione carbonica le due idee si incontrano: è una macerazione con dentro una fermentazione.",
   "Fermenter, c'est transformer, grâce aux levures ou aux bactéries. Macérer, c'est extraire, grâce au contact avec les pellicules. Saccharomyces cerevisiae fait la fermentation alcoolique, Oenococcus oeni la malolactique. Le gaz carbonique naît des fermentations et protège les macérations ; le dioxyde de soufre choisit qui peut travailler. Et dans la macération carbonique, les deux idées se rencontrent : c'est une macération avec une fermentation à l'intérieur.",
   "To ferment is to transform, thanks to yeasts or bacteria. To macerate is to extract, thanks to contact with the skins. Saccharomyces cerevisiae carries out alcoholic fermentation, Oenococcus oeni malolactic conversion. Carbon dioxide is born from fermentations and protects macerations; sulfur dioxide decides who gets to work. And in carbonic maceration the two ideas meet: it is a maceration with a fermentation inside."),
  v:()=>fSvg(`${fD(.1,xBox(20,30,134,30,w3("FERMENTARE = trasformare","FERMENTER = transformer","FERMENT = transform"),"rgba(212,162,58,.45)"))}${fD(.3,xBox(166,30,134,30,w3("MACERARE = estrarre","MACÉRER = extraire","MACERATE = extract"),"rgba(163,38,79,.55)"))}${fD(.7,zYeastBig(56,100,.8,"S. cerevisiae"))}${fD(1,zBactBig(128,100,null,"O. oeni"))}${fD(1.3,zGas(214,98,"CO₂","#2e6aa0",w3("protegge","protège","protects")))}${fD(1.6,zGas(278,98,"SO₂","#b8733a",w3("seleziona","sélectionne","selects")))}${fD(2.2,fChip(160,168,w3("carbonica = macerazione + fermentazione","carbonique = macération + fermentation","carbonic = maceration + fermentation"),"rgba(110,22,48,.9)"))}`)}
]},

/* ===================== CO2 vs SO2 ===================== */
{id:"co2so2",sec:"c",ch:"vin",ic:"order",nw:1,t:I3("CO₂ e SO₂: due gas da non confondere","CO₂ et SO₂ : deux gaz à ne pas confondre","CO₂ and SO₂: two gases not to confuse"),s:[
 {h:I3("Due sigle quasi uguali","Deux sigles presque identiques","Two almost identical formulas"),
  c:I3("CO₂ e SO₂ differiscono per una sola lettera, ma nel vino fanno cose completamente diverse. CO₂ è l'anidride carbonica: le bollicine, il gas delle fermentazioni. SO₂ è l'anidride solforosa: il conservante del vino, quello dei solfiti indicati in etichetta. Vediamo da dove vengono, quando intervengono e perché.",
   "CO₂ et SO₂ ne diffèrent que d'une lettre, mais dans le vin ils font des choses complètement différentes. Le CO₂ est le gaz carbonique, ou dioxyde de carbone : les bulles, le gaz des fermentations. Le SO₂ est le dioxyde de soufre, ou anhydride sulfureux : le conservateur du vin, celui des sulfites indiqués sur l'étiquette. Voyons d'où ils viennent, quand ils interviennent et pourquoi.",
   "CO₂ and SO₂ differ by just one letter, but in wine they do completely different things. CO₂ is carbon dioxide: the bubbles, the gas of fermentation. SO₂ is sulfur dioxide: wine's preservative, the source of the sulfites declared on the label. Let's see where they come from, when they act and why."),
  v:()=>fSvg(`${fD(.1,zGas(90,84,"CO₂","#2e6aa0",w3("anidride carbonica","gaz carbonique","carbon dioxide")))}${fD(.4,zGas(230,84,"SO₂","#b8733a",w3("anidride solforosa","dioxyde de soufre","sulfur dioxide")))}${fD(.8,fT(160,90,"≠",26,"#f3cd8a","middle",900))}${fD(1.2,fChip(90,140,w3("bollicine · fermentazioni","bulles · fermentations","bubbles · fermentation")))}${fD(1.5,fChip(230,140,w3("conservante · solfiti","conservateur · sulfites","preservative · sulfites"),"rgba(110,22,48,.85)"))}${fD(1.9,fT(90,170,w3("C = carbonio","C = carbone","C = carbon"),8,"#bfe3f5","middle",800))}${fD(2.1,fT(230,170,w3("S = zolfo","S = soufre","S = sulfur"),8,"#f3cd8a","middle",800))}`)},
 {h:I3("La CO₂ nasce dalla fermentazione","Le CO₂ naît de la fermentation","CO₂ is born from fermentation"),
  c:I3("L'anidride carbonica è prodotta naturalmente dai lieviti durante la fermentazione alcolica, insieme all'alcol, e in piccola quantità dai batteri della malolattica. Ogni litro di mosto ne libera circa 40-50 litri. È più pesante dell'aria e si accumula in basso: nelle cantine durante la vendemmia può essere mortale, per questo si ventilano i locali e si usano rilevatori.",
   "Le gaz carbonique est produit naturellement par les levures pendant la fermentation alcoolique, avec l'alcool, et en petite quantité par les bactéries de la malolactique. Chaque litre de moût en libère environ 40 à 50 litres. Il est plus lourd que l'air et s'accumule en bas : dans les chais, pendant les vendanges, il peut être mortel, c'est pourquoi on ventile les locaux et on utilise des détecteurs.",
   "Carbon dioxide is produced naturally by yeasts during alcoholic fermentation, together with alcohol, and in small amounts by malolactic bacteria. Each litre of must releases about 40 to 50 litres of it. It is heavier than air and collects low down: in wineries at harvest time it can be deadly, which is why rooms are ventilated and detectors are used."),
  v:()=>fSvg(`${fTank(40,50,90,120,{col:"#e9d27a",lv:.8})}${zBubbles(48,74,74,90,16)}${fD(.3,fYeast(70,140)+fYeast(100,126))}${xCO2(150,40,140,6)}${xCO2(150,60,140,5)}${fD(.8,xBoxD(156,80,150,26,w3("1 L di mosto → 40-50 L di CO₂","1 L de moût → 40-50 L de CO₂","1 L must → 40-50 L CO₂")))}${fD(1.4,`<rect x="150" y="150" width="160" height="30" fill="rgba(160,210,240,.25)"/>`+fT(230,169,w3("⚠ più pesante dell'aria","⚠ plus lourd que l'air","⚠ heavier than air"),8,"#ffd2d6","middle",800))}${fD(1.8,fMan(286,148,.7))}`)},
 {h:I3("La CO₂ che protegge","Le CO₂ qui protège","CO₂ as a shield"),
  c:I3("Proprio perché è pesante e non contiene ossigeno, l'anidride carbonica forma una coperta protettiva sopra il mosto e il vino. Si usa per riempire la vasca nella macerazione carbonica, per proteggere l'uva nella macerazione a freddo sotto forma di ghiaccio secco, e come gas inerte, insieme all'azoto e all'argon, per riempire lo spazio vuoto di vasche e bottiglie ed evitare l'ossidazione.",
   "Justement parce qu'il est lourd et ne contient pas d'oxygène, le gaz carbonique forme une couverture protectrice au-dessus du moût et du vin. On l'utilise pour remplir la cuve dans la macération carbonique, pour protéger le raisin pendant la macération à froid sous forme de neige carbonique, et comme gaz inerte, avec l'azote et l'argon, pour remplir l'espace vide des cuves et des bouteilles et éviter l'oxydation.",
   "Precisely because it is heavy and contains no oxygen, carbon dioxide forms a protective blanket over must and wine. It is used to fill the vat in carbonic maceration, to protect the grapes during cold soak in the form of dry ice, and as an inert gas, together with nitrogen and argon, to fill the empty space in vats and bottles and prevent oxidation."),
  v:()=>fSvg(`${fTank(30,46,100,124,{col:"#8a1f3e",lv:.6})}${`<rect x="32" y="62" width="96" height="44" fill="rgba(160,210,240,.3)"/>`}${xCO2(40,84,80,5)}${fD(.4,zCross(80,30,`<circle cx="80" cy="30" r="9" fill="#e0505a" opacity=".8"/>`+fT(80,33,"O₂",7,"#fff","middle",900)))}${fD(.8,xSide(150,40,158,[w3("macerazione carbonica","macération carbonique","carbonic maceration"),w3("ghiaccio secco a freddo","neige carbonique à froid","dry ice for cold soak"),w3("gas inerte: CO₂, azoto, argon","gaz inerte : CO₂, azote, argon","inert gas: CO₂, nitrogen, argon")],.8))}${fD(2,zIce(196,150))}`)},
 {h:I3("La CO₂ nel bicchiere","Le CO₂ dans le verre","CO₂ in the glass"),
  c:I3("Nei vini fermi resta sempre un po' di anidride carbonica disciolta, soprattutto nei bianchi giovani: dà freschezza e vivacità. Nei rossi si tiene bassa, perché un pizzicore renderebbe i tannini più duri. Nei frizzanti e negli spumanti diventa protagonista: nello Champagne la seconda fermentazione in bottiglia crea circa 6 atmosfere. Per i vini spumanti più semplici si può anche aggiungere per gassificazione.",
   "Dans les vins tranquilles, il reste toujours un peu de gaz carbonique dissous, surtout dans les blancs jeunes : il apporte fraîcheur et vivacité. Dans les rouges, on le garde bas, car un picotement rendrait les tanins plus durs. Dans les perlants et les effervescents, il devient le protagoniste : dans le champagne, la prise de mousse en bouteille crée environ 6 atmosphères. Pour les vins mousseux les plus simples, on peut aussi l'ajouter par gazéification.",
   "Still wines always keep a little dissolved carbon dioxide, especially young whites: it gives freshness and liveliness. In reds it is kept low, because a prickle would make the tannins seem harsher. In semi-sparkling and sparkling wines it takes centre stage: in Champagne the second fermentation in bottle creates about 6 atmospheres. For the simplest sparkling wines it can also be added by carbonation."),
  v:()=>fSvg(`${fD(.1,fGlass(52,100,"#efe1a0",1.3)+zBubbles(42,70,20,30,3)+fT(52,150,w3("bianco giovane","blanc jeune","young white"),7,"#fff4dc","middle",800,14))}${fD(.4,fGlass(124,100,"#7a1d3a",1.3)+fT(124,150,w3("rosso: poca CO₂","rouge : peu de CO₂","red: little CO₂"),7,"#fff4dc","middle",800,14))}${fD(.7,fGlass(196,100,"#efe1a0",1.3)+zBubbles(186,70,20,30,10)+fT(196,150,w3("spumante","effervescent","sparkling"),7,"#fff4dc","middle",800))}${fD(1.1,zGauge(268,96,6,8,"≈ 6 atm"))}${fD(1.6,fChip(160,178,w3("freschezza · pizzicore · spuma","fraîcheur · picotement · mousse","freshness · prickle · mousse"),"rgba(46,106,160,.9)"))}`)},
 {h:I3("La SO₂: da dove viene","Le SO₂ : d'où il vient","SO₂: where it comes from"),
  c:I3("L'anidride solforosa si aggiunge quasi sempre dall'esterno: come gas, come soluzione liquida, come polvere di metabisolfito di potassio, oppure bruciando dello zolfo nelle botti vuote per sanificarle. Ma anche i lieviti ne producono un po' durante la fermentazione: per questo un vino davvero senza solfiti non esiste. La scritta senza solfiti aggiunti significa solo che il produttore non ne ha aggiunti.",
   "Le dioxyde de soufre est presque toujours ajouté de l'extérieur : sous forme de gaz, de solution liquide, de poudre de métabisulfite de potassium, ou en brûlant une mèche de soufre dans les fûts vides pour les assainir. Mais les levures en produisent aussi un peu pendant la fermentation : c'est pourquoi un vin réellement sans sulfites n'existe pas. La mention sans sulfites ajoutés signifie seulement que le producteur n'en a pas ajouté.",
   "Sulfur dioxide is almost always added from outside: as a gas, as a liquid solution, as potassium metabisulfite powder, or by burning sulfur in empty barrels to sanitise them. But yeasts also make a little during fermentation: that is why a truly sulfite-free wine does not exist. The phrase no added sulfites only means the producer did not add any."),
  v:()=>fSvg(`${fD(.1,zGas(60,70,"SO₂","#b8733a"))}${fD(.4,xSide(110,30,196,[w3("gas o soluzione liquida","gaz ou solution liquide","gas or liquid solution"),w3("metabisolfito di potassio","métabisulfite de potassium","potassium metabisulfite"),w3("zolfo bruciato nelle botti","mèche de soufre dans les fûts","sulfur burnt in barrels")],.4))}${fD(1.5,fYeast(60,140))}${fD(1.6,fT(76,143,w3("anche i lieviti ne producono un po'","les levures en produisent aussi un peu","yeasts also make a little"),7.5,"#fff4dc","start",700))}${fD(2.1,fChip(160,178,w3("senza solfiti aggiunti ≠ senza solfiti","sans sulfites ajoutés ≠ sans sulfites","no added sulfites ≠ sulfite-free"),"rgba(110,22,48,.9)"))}`)},
 {h:I3("Il primo ruolo della SO₂: antisettico","Premier rôle du SO₂ : antiseptique","SO₂'s first role: antimicrobial"),
  c:I3("L'anidride solforosa frena i microrganismi indesiderati: i batteri acetici come Acetobacter, che trasformerebbero il vino in aceto, i batteri lattici quando non si vuole la malolattica, i lieviti selvaggi e Brettanomyces. Saccharomyces cerevisiae la tollera meglio: per questo, a dosi moderate, la SO₂ fa da arbitro e sceglie chi può lavorare.",
   "Le dioxyde de soufre freine les micro-organismes indésirables : les bactéries acétiques comme Acetobacter, qui transformeraient le vin en vinaigre, les bactéries lactiques quand on ne veut pas de malolactique, les levures sauvages et Brettanomyces. Saccharomyces cerevisiae le tolère mieux : c'est pourquoi, à dose modérée, le SO₂ joue l'arbitre et choisit qui peut travailler.",
   "Sulfur dioxide holds back unwanted microorganisms: acetic bacteria such as Acetobacter, which would turn wine into vinegar, lactic bacteria when malolactic is not wanted, wild yeasts and Brettanomyces. Saccharomyces cerevisiae tolerates it better: that is why, at moderate doses, SO₂ acts as referee and decides who gets to work."),
  v:()=>fSvg(`${fD(.1,zShield(60,96))}${[[w3("Acetobacter → aceto","Acetobacter → vinaigre","Acetobacter → vinegar"),fBug(140,46,"#c9a46a")],[w3("batteri lattici","bactéries lactiques","lactic bacteria"),fBug(140,76,"#9fd36a")],[w3("lieviti selvaggi","levures sauvages","wild yeasts"),fYeast(140,106)],["Brettanomyces",fYeast(140,136)]].map(([l,ic],i)=>fD(.4+i*.35,zCross(140,46+i*30,ic,9)+fT(162,49+i*30,l,7.5,"#fff4dc","start",800))).join("")}${fD(2,fYeast(140,170)+fT(162,173,w3("S. cerevisiae: la tollera ✓","S. cerevisiae : le tolère ✓","S. cerevisiae: tolerates it ✓"),7.5,"#9fe3b0","start",800))}`)},
 {h:I3("Il secondo ruolo: antiossidante","Deuxième rôle : antioxydant","The second role: antioxidant"),
  c:I3("L'ossigeno fa imbrunire il vino, spegne gli aromi freschi e produce acetaldeide, che dà un odore di mela ammaccata. La SO₂ blocca gli enzimi che ossidano il mosto, reagisce con l'ossigeno e si lega all'acetaldeide, cancellandone l'odore. I bianchi e i rosati, più fragili, ne hanno più bisogno dei rossi, che sono protetti in parte dai loro tannini.",
   "L'oxygène fait brunir le vin, éteint les arômes frais et produit de l'éthanal, qui donne une odeur de pomme blette. Le SO₂ bloque les enzymes qui oxydent le moût, réagit avec l'oxygène et se combine à l'éthanal, ce qui en efface l'odeur. Les blancs et les rosés, plus fragiles, en ont plus besoin que les rouges, protégés en partie par leurs tanins.",
   "Oxygen browns wine, dulls fresh aromas and produces acetaldehyde, which smells of bruised apple. SO₂ blocks the enzymes that oxidise the must, reacts with oxygen and binds to acetaldehyde, erasing its smell. Whites and rosés, being more fragile, need more of it than reds, which are partly protected by their tannins."),
  v:()=>fSvg(`${fD(.1,fGlass(60,92,"#c98a2a",1.4))}${fD(.3,fT(60,160,w3("ossidato","oxydé","oxidised"),8,"#ffd2d6","middle",800))}${fD(.5,fChip(60,24,w3("mela ammaccata","pomme blette","bruised apple"),"rgba(176,42,60,.85)"))}${fD(.9,zShield(140,96))}${fD(1.2,fGlass(220,92,"#efe1a0",1.4))}${fD(1.4,fT(220,160,w3("protetto","protégé","protected"),8,"#9fe3b0","middle",800))}${fD(1.7,fChip(160,180,w3("blocca gli enzimi · lega l'acetaldeide","bloque les enzymes · fixe l'éthanal","blocks enzymes · binds acetaldehyde"),"rgba(46,106,160,.9)"))}${fD(2.2,fChip(240,24,w3("bianchi e rosati > rossi","blancs et rosés > rouges","whites and rosés > reds"),"rgba(110,22,48,.85)"))}`)},
 {h:I3("SO₂ libera e SO₂ combinata","SO₂ libre et SO₂ combiné","Free and bound SO₂"),
  c:I3("Una volta nel vino, parte della SO₂ si lega ad altre sostanze, come zuccheri e acetaldeide: è la SO₂ combinata, che non protegge più. Resta attiva solo la SO₂ libera. La somma delle due è la SO₂ totale, quella limitata dalla legge. Il pH conta molto: più il vino è acido, più la SO₂ libera è efficace, e meno ne serve. I vini dolci, ricchi di zucchero che la lega e a rischio di rifermentazione, ne richiedono di più.",
   "Une fois dans le vin, une partie du SO₂ se combine à d'autres substances, comme les sucres et l'éthanal : c'est le SO₂ combiné, qui ne protège plus. Seul le SO₂ libre reste actif. La somme des deux est le SO₂ total, celui que limite la loi. Le pH compte beaucoup : plus le vin est acide, plus le SO₂ libre est efficace, et moins il en faut. Les vins doux, riches en sucre qui le fixe et exposés à une refermentation, en demandent davantage.",
   "Once in the wine, some of the SO₂ binds to other substances, such as sugars and acetaldehyde: this is bound SO₂, which no longer protects. Only free SO₂ stays active. The two added together make total SO₂, the figure the law limits. pH matters a lot: the more acidic the wine, the more effective free SO₂ is, and the less is needed. Sweet wines, rich in sugar that binds it and at risk of refermenting, need more."),
  v:()=>fSvg(`${fD(.1,`<rect x="30" y="40" width="70" height="120" rx="6" fill="rgba(255,248,232,.1)" stroke="#e8dccf"/><rect x="32" y="100" width="66" height="58" fill="#b8733a" opacity=".55"/><rect x="32" y="66" width="66" height="34" fill="#f3cd8a" opacity=".85"/>`)}${fD(.4,fT(65,86,w3("libera","libre","free"),8,"#2a1b20","middle",900))}${fD(.6,fT(65,132,w3("combinata","combiné","bound"),8,"#fff","middle",900))}${fD(.8,fT(65,176,w3("= totale","= total","= total"),8,"#f3cd8a","middle",900))}${fD(1.1,xSide(120,40,188,[w3("solo la libera protegge","seul le libre protège","only free SO₂ protects"),w3("pH basso → più efficace","pH bas → plus efficace","low pH → more effective"),w3("vini dolci → ne serve di più","vins doux → il en faut plus","sweet wines → need more")],1.1))}`)},
 {h:I3("Quando si aggiunge la SO₂","Quand on ajoute le SO₂","When SO₂ is added"),
  c:I3("La SO₂ accompagna tutta la vita del vino. Si aggiunge all'arrivo dell'uva e alla pigiatura, per proteggere il mosto e selezionare i lieviti. Si evita prima della malolattica, se la si vuole, perché fermerebbe i batteri. Si aggiunge subito dopo la fine delle fermentazioni, per stabilizzare il vino; durante l'affinamento, ai travasi e alle colmature; e infine all'imbottigliamento, per regolare la SO₂ libera.",
   "Le SO₂ accompagne toute la vie du vin. On l'ajoute à l'arrivée du raisin et au foulage, pour protéger le moût et sélectionner les levures. On l'évite avant la malolactique, si on la souhaite, car il arrêterait les bactéries. On l'ajoute juste après la fin des fermentations, pour stabiliser le vin ; pendant l'élevage, lors des soutirages et des ouillages ; et enfin à la mise en bouteille, pour ajuster le SO₂ libre.",
   "SO₂ accompanies the wine's whole life. It is added when the grapes arrive and at crushing, to protect the must and select the yeasts. It is avoided before malolactic, if malolactic is wanted, because it would stop the bacteria. It is added right after the fermentations end, to stabilise the wine; during maturation, at racking and topping up; and finally at bottling, to adjust the free SO₂."),
  v:()=>fSvg(zTL([[0,1,w3("SO₂ ✓ protezione","SO₂ ✓ protection","SO₂ ✓ protection"),"#b8733a",0],[2,2,w3("CO₂ prodotta","CO₂ produit","CO₂ produced"),"#2e6aa0",1],[4,4,w3("SO₂ ✗ se si vuole","SO₂ ✗ si désirée","SO₂ ✗ if wanted"),"#7a7a7a",0],[4,4,w3("CO₂ (poca)","CO₂ (peu)","CO₂ (little)"),"#2e6aa0",1],[5,5,w3("SO₂ ✓ stabilità","SO₂ ✓ stabilité","SO₂ ✓ stability"),"#b8733a",2],[6,6,w3("SO₂ ✓ finale","SO₂ ✓ final","SO₂ ✓ final"),"#b8733a",0]],{hi:[0,1,5,6]})+fD(.1,xLab(24,26,w3("SO₂ e CO₂ lungo la vinificazione","SO₂ et CO₂ au fil de la vinification","SO₂ and CO₂ through winemaking"))))},
 {h:I3("La giusta dose","La bonne dose","The right dose"),
  c:I3("Troppa SO₂ si sente: un odore di fiammifero bruciato, che pizzica il naso e copre il frutto. Troppo poca, e il vino si ossida o si altera. La legge europea fissa dei massimi di SO₂ totale: più bassi per i rossi secchi, circa 150 milligrammi per litro, più alti per i bianchi e i rosati secchi, circa 200, e ancora più alti per i vini dolci. Sopra i 10 milligrammi per litro l'etichetta deve indicare contiene solfiti. I vini biologici hanno limiti più bassi.",
   "Trop de SO₂ se sent : une odeur d'allumette brûlée, qui pique le nez et masque le fruit. Trop peu, et le vin s'oxyde ou s'altère. La loi européenne fixe des maximums de SO₂ total : plus bas pour les rouges secs, environ 150 milligrammes par litre, plus élevés pour les blancs et rosés secs, environ 200, et encore plus élevés pour les vins doux. Au-delà de 10 milligrammes par litre, l'étiquette doit indiquer contient des sulfites. Les vins biologiques ont des limites plus basses.",
   "Too much SO₂ can be smelt: a burnt-match smell that stings the nose and masks the fruit. Too little, and the wine oxidises or spoils. European law sets maximum levels of total SO₂: lower for dry reds, about 150 milligrams per litre, higher for dry whites and rosés, about 200, and higher still for sweet wines. Above 10 milligrams per litre the label must say contains sulfites. Organic wines have lower limits."),
  v:()=>fSvg(`${[[w3("rossi secchi","rouges secs","dry reds"),150,"#7a1d3a"],[w3("bianchi e rosati secchi","blancs et rosés secs","dry whites, rosés"),200,"#d9c23a"],[w3("vini dolci","vins doux","sweet wines"),300,"#c98a2a"]].map(([l,v,c],i)=>{ const h=v*.36; return fD(.2+i*.35,`<rect x="${36+i*56}" y="${150-h}" width="40" height="${h}" rx="4" fill="${c}"/>`+fT(56+i*56,144-h,(i===2?"> ":"≈ ")+v,7.5,"#fff4dc","middle",800)+fT(56+i*56,162,l,6.2,"#fff4dc","middle",700,12)); }).join("")}${fD(1.4,fT(110,30,w3("SO₂ totale max · mg/L","SO₂ total max · mg/L","max total SO₂ · mg/L"),7.5,"#f3cd8a","middle",800))}${fD(1.6,xSide(210,40,100,[w3("troppa: fiammifero","trop : allumette","too much: match"),w3("poca: ossidazione","trop peu : oxydation","too little: oxidation"),w3("> 10 mg/L: «solfiti»","> 10 mg/L : « sulfites »","> 10 mg/L: 'sulfites'")],1.6))}`)},
 {h:I3("CO₂ e SO₂ a confronto","CO₂ et SO₂ comparés","CO₂ and SO₂ compared"),
  c:I3("Ricapitoliamo. La CO₂ nasce dalle fermentazioni, protegge dall'ossigeno come una coperta, dà freschezza e crea le bollicine; in cantina è pericolosa da respirare. La SO₂ si aggiunge quasi sempre, protegge dai microbi e dall'ossidazione, seleziona i lieviti e può bloccare la malolattica; troppa si sente come fiammifero bruciato e va indicata in etichetta.",
   "Récapitulons. Le CO₂ naît des fermentations, protège de l'oxygène comme une couverture, apporte de la fraîcheur et crée les bulles ; au chai, il est dangereux à respirer. Le SO₂ est presque toujours ajouté, protège des microbes et de l'oxydation, sélectionne les levures et peut bloquer la malolactique ; en excès, il sent l'allumette brûlée, et il doit être indiqué sur l'étiquette.",
   "To recap. CO₂ is born from fermentations, protects from oxygen like a blanket, gives freshness and creates the bubbles; in the winery it is dangerous to breathe. SO₂ is almost always added, protects against microbes and oxidation, selects the yeasts and can block malolactic; in excess it smells of burnt match, and it must be declared on the label."),
  v:()=>fSvg(zTbl(8,20,[64,118,122],["",`CO₂ · ${w3("anidride carbonica","gaz carbonique","carbon dioxide")}`,`SO₂ · ${w3("anidride solforosa","dioxyde de soufre","sulfur dioxide")}`],[[w3("origine","origine","origin"),w3("fermentazioni (lieviti, batteri)","fermentations (levures, bactéries)","fermentations (yeasts, bacteria)"),w3("aggiunta; un po' dai lieviti","ajouté ; un peu par les levures","added; a little from yeasts")],[w3("ruolo","rôle","role"),w3("coperta anti-ossigeno, bollicine","couverture anti-oxygène, bulles","oxygen blanket, bubbles"),w3("antisettico + antiossidante","antiseptique + antioxydant","antimicrobial + antioxidant")],[w3("quando","quand","when"),w3("FA, malolattica, presa di spuma","FA, malolactique, prise de mousse","AF, malolactic, 2nd ferm."),w3("uva, pigiatura, dopo FA, affinamento, bottiglia","raisin, foulage, après FA, élevage, bouteille","grapes, crush, after AF, ageing, bottling")],[w3("al gusto","en bouche","in taste"),w3("freschezza, pizzicore","fraîcheur, picotement","freshness, prickle"),w3("se in eccesso: fiammifero","en excès : allumette","in excess: burnt match")],[w3("rischio","risque","risk"),w3("asfissia in cantina","asphyxie au chai","suffocation in winery"),w3("allergie: «contiene solfiti»","allergies : « contient des sulfites »","allergies: 'contains sulfites'")]],{sz:6.1,dd:.3}))},
 {h:I3("Da ricordare","À retenir","Key points"),
  c:I3("CO₂ uguale carbonio: nasce dai lieviti, fa le bollicine e protegge come una coperta. SO₂ uguale zolfo: la aggiunge il produttore, fa da guardiano contro microbi e ossigeno. Nelle macerazioni lavorano spesso insieme: la SO₂ frena i microbi, la CO₂ tiene lontano l'ossigeno.",
   "CO₂ égale carbone : il naît des levures, fait les bulles et protège comme une couverture. SO₂ égale soufre : c'est le producteur qui l'ajoute, il monte la garde contre les microbes et l'oxygène. Dans les macérations, ils travaillent souvent ensemble : le SO₂ freine les microbes, le CO₂ tient l'oxygène à distance.",
   "CO₂ means carbon: it comes from yeasts, makes the bubbles and protects like a blanket. SO₂ means sulfur: the producer adds it, and it stands guard against microbes and oxygen. In macerations they often work together: SO₂ holds back microbes, CO₂ keeps oxygen away."),
  v:()=>fSvg(`${fD(.1,zGas(80,78,"CO₂","#2e6aa0",w3("bollicine + coperta","bulles + couverture","bubbles + blanket")))}${fD(.4,zGas(240,78,"SO₂","#b8733a",w3("guardiano","gardien","guardian")))}${fD(.8,fTank(130,100,60,80,{col:"#5a1035",lv:.7}))}${fD(1.1,fChip(160,94,w3("insieme","ensemble","together")))}${fD(1.4,fCall(130,130,60,150,w3("SO₂: microbi ✗","SO₂ : microbes ✗","SO₂: microbes ✗")))}${fD(1.7,fCall(190,120,260,150,w3("CO₂: ossigeno ✗","CO₂ : oxygène ✗","CO₂: oxygen ✗")))}`)}
]}
);
